//! 🧪️ Supplied native bytes return without copy and close only through their still-live original supplier.
use semio_framework_job::*;
#[cfg(test)] use semio_framework_job_payload::payload_pages_and_ledger::JobPayloadStream;
#[path="../../../🧪️testing/📬️payload/🦀️.rs"]
mod original_payload;
#[global_allocator]
static HEAP:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
static RETURNS:OriginalJobPageReturnRegistry<1>=OriginalJobPageReturnRegistry::new();
static CONTIGUOUS_RETURNS:OriginalJobBytesReturnRegistry<1>=OriginalJobBytesReturnRegistry::with_return_wake(original_contiguous_notice);
fn original_contiguous_notice(){}

#[test]
fn original_contiguous_bytes_keep_exact_birth_fill_and_return_on_the_same_source(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../📦️bytes/🔣️.json")).unwrap();let length=law["capacityBytes"].as_u64().unwrap()as usize;
 let mut original=original_payload::OriginalTestPayload::admit_single_page(OperationId(96004),Generation(10),JobPayloadStream::CommitOutput,b"original contiguous",JOB_PAYLOAD_PAGE_BYTES);let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:65536,maximum_capacity_bytes:32768,maximum_release_bytes:1048576,maximum_depth:64};let mut bytes=None;
 for denied in[RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_capacity_bytes:16384,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(answer,heap)=original_payload::observe(||original.original_turn(denied,|_,cx|OriginalContiguousJobBytes::admit(length,&mut bytes,cx)));assert!(!answer.unwrap());assert!(bytes.is_none());assert_eq!(heap,(0,0));}
 let(answer,heap)=original_payload::observe(||original.original_turn(grant,|_,cx|OriginalContiguousJobBytes::admit(length,&mut bytes,cx)));assert!(!answer.unwrap());assert_eq!(heap,(0,0));assert!(!bytes.as_ref().unwrap().ready());let(answer,heap)=original_payload::observe(||original.original_turn(grant,|_,cx|OriginalContiguousJobBytes::admit(length,&mut bytes,cx)));assert!(answer.unwrap());assert_eq!(heap,(length,0));let source=original.caller.turn(grant,|cx|Ok(cx.original_source_parent()?.source_identity()?)).unwrap();
 let data:Vec<u8>=(0..length).map(|index|(index%251)as u8).collect();for part in data.chunks(4096){let(answer,heap)=original_payload::observe(||original.original_turn(grant,|_,cx|bytes.as_mut().unwrap().append(part,cx)));assert!(answer.unwrap());assert_eq!(heap,(0,0));}let pointer=bytes.as_ref().unwrap().borrowed_bytes().unwrap().as_ptr();
 let mut foreign=original_payload::OriginalTestPayload::admit_single_page(OperationId(96004),Generation(10),JobPayloadStream::CommitOutput,b"foreign",JOB_PAYLOAD_PAGE_BYTES);let(answer,heap)=original_payload::observe(||foreign.original_turn(grant,|_,cx|bytes.as_mut().unwrap().append(&[],cx)));assert!(answer.is_err());assert_eq!(heap,(0,0));foreign.close();
 let mut reservation=original.caller.turn(grant,|cx|Ok(CONTIGUOUS_RETURNS.reserve(cx)?.unwrap())).unwrap();let mut supplied=None;let(answer,heap)=original_payload::observe(||original.original_turn(grant,|_,cx|reservation.publish(&mut bytes,&mut supplied,cx)));assert!(answer.unwrap());assert_eq!(heap,(0,0));assert!(bytes.is_none());let supplied=supplied.unwrap();assert_eq!(supplied.bytes(),data.as_slice());assert_eq!(supplied.bytes().as_ptr(),pointer);assert_eq!(supplied.source_identity(),source);assert_eq!(original_payload::observe(||drop(supplied)).1,(0,0));assert!(CONTIGUOUS_RETURNS.has_returned_source(source));
 for denied in[RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_copy_bytes:0,..grant},RetainedCloneGrant{maximum_release_bytes:16384,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(answer,heap)=original_payload::observe(||original.original_turn(denied,|_,cx|CONTIGUOUS_RETURNS.close_returned_step(cx)));assert_eq!(answer.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));assert!(CONTIGUOUS_RETURNS.retains_source(source));}
 let mut released=0;for turn in 0..24{if !CONTIGUOUS_RETURNS.retains_source(source){break}let(answer,heap)=original_payload::observe(||original.original_turn(grant,|_,cx|CONTIGUOUS_RETURNS.close_returned_step(cx)));let step=answer.unwrap();assert!(!matches!(step,InteractiveJobCloseStep::Complete{..}));let progress=step.progress();assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));released+=heap.1;assert!(turn<23)}assert_eq!(released,law["supplierReleaseBytes"].as_u64().unwrap()as usize);drop(reservation);original.close();assert_eq!(original_payload::observe(||drop(original)).1,(0,0));eprintln!("[DEBUG] exact contiguous original receiving and fill, foreign-source refusal, unchanged pointer through consumer borrow/return, zero consumer heap, actual per-axis denied and exact16385-byte same-source backing close before loan return");
}
static ORDERED_RETURNS:OriginalJobPageReturnRegistry<3>=OriginalJobPageReturnRegistry::new();
static WAKE_SOURCE:std::sync::atomic::AtomicUsize=std::sync::atomic::AtomicUsize::new(0);
static WAKE_COUNT:std::sync::atomic::AtomicUsize=std::sync::atomic::AtomicUsize::new(0);
static NOTIFIED_RETURNS:OriginalJobPageReturnRegistry<1>=OriginalJobPageReturnRegistry::with_return_wake(original_return_notice);
fn original_return_notice(){let source=WAKE_SOURCE.load(std::sync::atomic::Ordering::Acquire);assert!(NOTIFIED_RETURNS.has_returned_source(source));WAKE_COUNT.fetch_add(1,std::sync::atomic::Ordering::AcqRel);}

#[test]
fn original_supplied_page_notification_observes_published_return_without_owner_or_closure_birth(){
 let mut original=original_payload::OriginalTestPayload::admit_single_page(OperationId(96003),Generation(9),JobPayloadStream::CommitOutput,b"return wake",JOB_PAYLOAD_PAGE_BYTES);let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:JOB_PAYLOAD_PAGE_BYTES,maximum_release_bytes:1048576,maximum_depth:64};
 let source=original.caller.turn(grant,|cx|Ok(cx.original_source_parent()?.source_identity()?)).unwrap();WAKE_SOURCE.store(source,std::sync::atomic::Ordering::Release);WAKE_COUNT.store(0,std::sync::atomic::Ordering::Release);
 let mut reservation=original.caller.turn(grant,|cx|Ok(NOTIFIED_RETURNS.reserve(cx)?.unwrap())).unwrap();let page=original.original_turn(grant,|builder,cx|builder.supply_last_page(&mut reservation,cx)).unwrap().unwrap();assert_eq!(WAKE_COUNT.load(std::sync::atomic::Ordering::Acquire),0);assert!(!NOTIFIED_RETURNS.has_returned_source(source));
 assert_eq!(original_payload::observe(||drop(page)).1,(0,0));assert_eq!(WAKE_COUNT.load(std::sync::atomic::Ordering::Acquire),1);assert!(NOTIFIED_RETURNS.has_returned_source(source));
 for turn in 0..32{if !NOTIFIED_RETURNS.retains_source(source){break}original.original_turn(grant,|_,cx|NOTIFIED_RETURNS.close_returned_step(cx)).unwrap();assert!(turn<31)}
 let reservation=original.caller.turn(grant,|cx|Ok(NOTIFIED_RETURNS.reserve(cx)?.unwrap())).unwrap();assert_eq!(original_payload::observe(||drop(reservation)).1,(0,0));assert_eq!(WAKE_COUNT.load(std::sync::atomic::Ordering::Acquire),2);
 for turn in 0..16{if !NOTIFIED_RETURNS.retains_source(source){break}original.original_turn(grant,|_,cx|NOTIFIED_RETURNS.close_returned_step(cx)).unwrap();assert!(turn<15)}original.close();println!("[DEBUG] native actual page and cancelled reservation publish returned slot before reentrant preowned callback; no heap birth/release or closure/source copy at notification");
}
#[test]
fn original_supplied_page_returns_same_backing_before_original_source_close(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../🔣️.json")).unwrap();assert_eq!(corpus["pageBytes"],JOB_PAYLOAD_PAGE_BYTES);assert_eq!(corpus["operationPages"],JOB_PAYLOAD_OPERATION_PAGES);
 let mut original=original_payload::OriginalTestPayload::admit_single_page(OperationId(96001),Generation(7),JobPayloadStream::CommitOutput,b"original supplier",JOB_PAYLOAD_PAGE_BYTES);let pointer=original.builder.published().unwrap().single_page().unwrap().as_ptr();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:JOB_PAYLOAD_PAGE_BYTES,maximum_release_bytes:1048576,maximum_depth:64};
 let(source,reservation)=original.caller.turn(grant,|cx|Ok((cx.original_source_parent()?.source_identity()?,RETURNS.reserve(cx)?.unwrap()))).unwrap();let mut reservation=reservation;assert!(RETURNS.retains_source(source));let mut foreign=original_payload::OriginalTestPayload::admit_single_page(OperationId(96001),Generation(7),JobPayloadStream::CommitOutput,b"foreign supplier",JOB_PAYLOAD_PAGE_BYTES);let(answer,heap)=original_payload::observe(||foreign.original_turn(grant,|_,cx|original.builder.supply_last_page(&mut reservation,cx)));assert!(answer.is_err());assert_eq!(heap,(0,0));assert_eq!(original.builder.published().unwrap().single_page().unwrap().as_ptr(),pointer);
 let(answer,heap)=original_payload::observe(||original.caller.turn(grant,|cx|RETURNS.reserve(cx)));assert!(answer.unwrap().is_none());assert_eq!(heap,(0,0));assert_eq!(original.caller.receipt(),Default::default());
 for denied in[RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_copy_bytes:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(answer,heap)=original_payload::observe(||original.original_turn(denied,|builder,cx|builder.supply_last_page(&mut reservation,cx)));assert!(answer.unwrap().is_none());assert_eq!(heap,(0,0));assert_eq!(original.builder.published().unwrap().single_page().unwrap().as_ptr(),pointer);}
 let(answer,heap)=original_payload::observe(||original.original_turn(grant,|builder,cx|builder.supply_last_page(&mut reservation,cx)));let page=answer.unwrap().unwrap();assert_eq!(heap,(0,0));assert_eq!(page.bytes().as_ptr(),pointer);assert_eq!(page.bytes(),b"original supplier");assert_eq!(page.source_identity(),source);assert!(original.builder.published().unwrap().terminal_is_empty());assert_eq!(original_payload::observe(||drop(reservation)).1,(0,0));
 let(answer,heap)=original_payload::observe(||original.caller.retire_step(grant));assert!(answer.is_err());assert_eq!(heap,(0,0));original.caller.cancel().cancel_now();assert_eq!(original_payload::observe(||drop(page)).1,(0,0));assert!(RETURNS.retains_source(source));let(answer,heap)=original_payload::observe(||foreign.original_turn(grant,|_,cx|RETURNS.close_returned_step(cx)));assert_eq!(answer.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));assert!(RETURNS.retains_source(source));foreign.close();assert_eq!(original_payload::observe(||drop(foreign)).1,(0,0));
 for denied in[RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_copy_bytes:0,..grant},RetainedCloneGrant{maximum_release_bytes:JOB_PAYLOAD_PAGE_BYTES-1,..grant},RetainedCloneGrant{maximum_depth:1,..grant}]{let(answer,heap)=original_payload::observe(||original.original_turn(denied,|_,cx|RETURNS.close_returned_step(cx)));assert_eq!(answer.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));assert!(RETURNS.retains_source(source));}
 let mut released=0;for turn in 0..16{if !RETURNS.retains_source(source){break}let(answer,heap)=original_payload::observe(||original.original_turn(grant,|_,cx|RETURNS.close_returned_step(cx)));let progress=answer.unwrap().progress();assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));released+=heap.1;assert!(turn<15);}assert_eq!(released,JOB_PAYLOAD_PAGE_BYTES);assert!(!RETURNS.retains_source(source));original.close();assert_eq!(original_payload::observe(||drop(original)).1,(0,0));println!("[DEBUG] original supplied page exact pointer/zero-copy/full-registry denial/consumer return/page allocator receipt/source-loan-before-close/terminalDrop0");
}

#[test]
fn original_supplied_pages_preserve_ordinals_and_sealed_prefix_during_partial_transfer(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../🔣️.json")).unwrap();let mut bytes=vec![0u8;2*JOB_PAYLOAD_PAGE_BYTES+7];for(index,byte)in bytes.iter_mut().enumerate(){*byte=(index/JOB_PAYLOAD_PAGE_BYTES)as u8;}
 let mut original=original_payload::OriginalTestPayload::admit(OperationId(96002),Generation(8),JobPayloadStream::CommitOutput,&bytes,JOB_PAYLOAD_PAGE_BYTES);let pointers=std::array::from_fn::<_,3,_>(|index|original.builder.published().unwrap().page(index).unwrap().as_ptr());let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:JOB_PAYLOAD_PAGE_BYTES,maximum_release_bytes:1048576,maximum_depth:64};let source=original.caller.turn(grant,|cx|Ok(cx.original_source_parent()?.source_identity()?)).unwrap();let mut pages:[Option<OriginalSuppliedJobPage>;3]=std::array::from_fn(|_|None);
 for row in corpus["pageOrder"].as_array().unwrap(){let index=row.as_u64().unwrap()as usize;let mut reservation=original.caller.turn(grant,|cx|Ok(ORDERED_RETURNS.reserve(cx)?.unwrap())).unwrap();let(answer,heap)=original_payload::observe(||original.original_turn(grant,|builder,cx|builder.supply_last_page(&mut reservation,cx)));let page=answer.unwrap().unwrap();assert_eq!(heap,(0,0));assert_eq!(page.original_page_index(),index);assert_eq!(page.bytes().as_ptr(),pointers[index]);assert!(page.bytes().iter().all(|byte|*byte==index as u8));assert_eq!(original.builder.published().unwrap().page_count(),index);pages[index]=Some(page);}
 assert!(original.builder.published().unwrap().terminal_is_empty());for(index,page)in pages.iter().enumerate(){assert_eq!(page.as_ref().unwrap().original_page_index(),index);assert_eq!(page.as_ref().unwrap().bytes().as_ptr(),pointers[index]);}assert_eq!(original_payload::observe(||drop(pages)).1,(0,0));let mut released=0;
 for turn in 0..32{if !ORDERED_RETURNS.retains_source(source){break}let(answer,heap)=original_payload::observe(||original.original_turn(grant,|_,cx|ORDERED_RETURNS.close_returned_step(cx)));let progress=answer.unwrap().progress();assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));released+=heap.1;assert!(turn<31);}assert_eq!(released,3*JOB_PAYLOAD_PAGE_BYTES);assert!(!ORDERED_RETURNS.retains_source(source));original.close();assert_eq!(original_payload::observe(||drop(original)).1,(0,0));println!("[DEBUG] original three-page ordinal/pointer conservation, valid sealed prefix after each transfer and exact same-source48KiB release");
}
